import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.Date;

/**
 * 商户店铺service
 */
@Service
@Slf4j
@Setter
public class MerchantBranchServiceImpl implements MerchantBranchService {

    @Autowired
    private ExternalMerchantBranchService externalMerchantBranchService;

    @Autowired
    private AuthBranchRepository authBranchRepository;

    /**
     * 绑定店铺
     * @param bindBranchInfoDTO
     * @param userDTO
     * @return
     */
    @Override
    public boolean bindBranch(BindBranchInfoDTO bindBranchInfoDTO, UserDTO userDTO) {
        log.info("bindBranch bindBranchInfoDTO:{}, userDTO:{}", JSON.toJSONString(bindBranchInfoDTO), JSON.toJSONString(userDTO));
        Preconditions.checkNotNull(bindBranchInfoDTO);
        Preconditions.checkNotNull(bindBranchInfoDTO.getSignParams());
        Preconditions.checkNotNull(bindBranchInfoDTO.getBranchInfo());
        Preconditions.checkNotNull(bindBranchInfoDTO.getBranchInfo().getExternalBranchNo());
        Preconditions.checkNotNull(bindBranchInfoDTO.getBranchInfo().getPlatformCode());

        MerchantBranchInfoDTO merchantBranchInfoDTO = bindBranchInfoDTO.getBranchInfo();
        // 查询绑定信息
        AuthBranchE authBranchE = authBranchRepository.selectByAccountIdAndExternalBranchNo(Long.parseLong(userDTO.getAccountId()),
                merchantBranchInfoDTO.getExternalBranchNo());
        if (authBranchE != null) {
            throw new GatewayException(GawErrorCodeEnum.ERROR_MERCHANT_BIND_BRANCH);
        }
        // 验签
        boolean signFlag = externalMerchantBranchService.verifyBranchSign(bindBranchInfoDTO.getSignParams());
        if (!signFlag) {
            throw new GatewayException(GawErrorCodeEnum.ERROR_BIND_BRANCH_SIGN);
        }
        // 绑定
        return authBranchRepository.insertBranch(convertAuthBranchDO(merchantBranchInfoDTO, userDTO));
    }

    /**
     * 转换AuthBranchDO
     * @param merchantBranchInfoDTO
     * @param userDTO
     * @return
     */
    private AuthBranchDO convertAuthBranchDO(MerchantBranchInfoDTO merchantBranchInfoDTO, UserDTO userDTO) {
        AuthBranchDO authBranchDO = new AuthBranchDO();
        // 账号id
        authBranchDO.setAccountId(Long.parseLong(userDTO.getAccountId()));
        // 店铺编码
        authBranchDO.setBranchNo(merchantBranchInfoDTO.getBranchNo());
        // 店铺名称
        //authBranchDO.setBranchName();
        // 网点外部代码
        authBranchDO.setExternalBranchNo(merchantBranchInfoDTO.getExternalBranchNo());
        // 客户编码
        authBranchDO.setPartnerNo(merchantBranchInfoDTO.getPartnerNo());
        // 平台code
        authBranchDO.setPlatformCode(merchantBranchInfoDTO.getPlatformCode());
        // 状态 未签约:unsigned， 已签约:signed
        authBranchDO.setStatus(BranchSignEnum.UNSIGNED.getCode());
        // 是否有效
        authBranchDO.setIsValid((byte) 1);
        // 创建时间
        authBranchDO.setGmtCreate(new Date());
        // 修改时间
        authBranchDO.setGmtModified(authBranchDO.getGmtCreate());

        return authBranchDO;
    }
}
"}

